#!/usr/bin/env bash
# Regenerate every harness adapter from the canonical AGENTS.md.
# Adapters are generated artifacts — do not edit them by hand.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"

HEADER_NOTE="<!-- GENERATED by scripts/sync-agent-configs.sh from AGENTS.md. Do not edit. -->"

log() { printf '  %-28s %s\n' "$1" "$2"; }

[ -f AGENTS.md ] || { echo "AGENTS.md not found in $ROOT" >&2; exit 1; }

echo "Syncing agent harness adapters from AGENTS.md"

# ---------------------------------------------------------------- Claude Code
# Pointer file + skill/agent discovery directories.
cat > CLAUDE.md <<EOF
$HEADER_NOTE

@AGENTS.md

# Claude Code specifics

Skills and subagents are discovered from \`.claude/skills/\` and \`.claude/agents/\`,
which are symlinks into \`shared/\`, \`mcu/\` and \`linux-embedded/\`. The canonical
source is always the track directory, never the symlink.

- Read \`AGENTS.md\` section 2 and pick the track before any other action.
- Invoke the review subagents proactively as listed in section 5 — no prompt needed.
- Hardware-destructive commands (section 3, rule 1) always require explicit confirmation,
  regardless of the permission mode in effect.
EOF
log "CLAUDE.md" "pointer written"

rm -rf .claude/skills .claude/agents
mkdir -p .claude/skills .claude/agents

for d in shared/skills/*/ mcu/skills/*/ linux-embedded/skills/*/; do
  [ -d "$d" ] || continue
  name="$(basename "$d")"
  ln -sfn "../../$d" ".claude/skills/$name"
done

for f in shared/agents/*.md mcu/agents/*.md linux-embedded/agents/*.md; do
  [ -f "$f" ] || continue
  ln -sfn "../../$f" ".claude/agents/$(basename "$f")"
done
log ".claude/skills" "$(find .claude/skills -maxdepth 1 -type l | wc -l) skills linked"
log ".claude/agents" "$(find .claude/agents -maxdepth 1 -type l | wc -l) agents linked"

# --------------------------------------------------------------- OpenAI Codex
# Codex reads AGENTS.md natively; only the CLI config is generated.
mkdir -p .codex
cat > .codex/config.toml <<'EOF'
# GENERATED by scripts/sync-agent-configs.sh. Do not edit.
# Codex reads ./AGENTS.md natively — this file only sets execution policy.

model = "gpt-5-codex"
approval_policy = "on-request"
sandbox_mode = "workspace-write"

[sandbox_workspace_write]
network_access = true

# Hardware-destructive tooling must never run unattended.
# Keep approval required for anything touching a device.
[shell_environment_policy]
inherit = "core"
EOF
log ".codex/config.toml" "written"

# --------------------------------------------------------------------- Cursor
mkdir -p .cursor/rules
{
  echo "---"
  echo "description: Embedded systems agentic development environment — core rules"
  echo "alwaysApply: true"
  echo "---"
  echo
  echo "$HEADER_NOTE"
  echo
  sed '1,2d' AGENTS.md
} > .cursor/rules/embedded-core.mdc

for track in mcu linux-embedded; do
  [ -f "$track/AGENTS.md" ] || continue
  {
    echo "---"
    echo "description: ${track} track rules and skill routing"
    echo "alwaysApply: false"
    echo "---"
    echo
    echo "$HEADER_NOTE"
    echo
    cat "$track/AGENTS.md"
  } > ".cursor/rules/${track}.mdc"
done
log ".cursor/rules" "$(ls .cursor/rules | wc -l) rule files"

# --------------------------------------------------------------- Gemini CLI
cat > GEMINI.md <<EOF
$HEADER_NOTE

# Embedded Agentic Development Environment

The canonical instructions are in \`AGENTS.md\` at the repository root. Read it first,
in full, before any other action.

@AGENTS.md
EOF
log "GEMINI.md" "pointer written"

# ------------------------------------------------------------------- Copilot
mkdir -p .github
{
  echo "$HEADER_NOTE"
  echo
  cat AGENTS.md
} > .github/copilot-instructions.md
log ".github/copilot-instructions.md" "written"

# ------------------------------------------------------------------ Continue
mkdir -p .continue/rules
{
  echo "---"
  echo "name: embedded-core"
  echo "alwaysApply: true"
  echo "---"
  echo
  cat AGENTS.md
} > .continue/rules/embedded-core.md
log ".continue/rules" "written"

# -------------------------------- DeepSeek / Qwen / generic AGENTS.md readers
# These read AGENTS.md directly. Provide the common alternative filenames as
# symlinks so no harness misses it.
for alias in .agent.md .rules.md; do
  ln -sfn AGENTS.md "$alias"
done
log "generic aliases" ".agent.md .rules.md -> AGENTS.md"

echo
echo "Done. Adapters are generated — edit AGENTS.md and re-run this script."
